#include <iostream>
#include <vector>
#include <cmath>

using namespace std;

const double epsilon = 1e-9;
const double PI = acos(-1.0);

class Vector {
public:
    int components[5];

    Vector(const int a[], const int b[]) {
        for (int i = 0; i < 5; i++) {
            components[i] = b[i] - a[i];
        }
    }

    double mag() const {
        double sumSquares = 0.0;
        for (int i = 0; i < 5; i++) {
            sumSquares += components[i] * components[i];
        }
        return sqrt(sumSquares);
    }

    int prod(const Vector& v) const {
        int dotProduct = 0;
        for (int i = 0; i < 5; i++) {
            dotProduct += components[i] * v.components[i];
        }
        return dotProduct;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int count;
    cin >> count;

    if (count > 11) {
        cout << 0 << "\n";
        return 0;
    }

    vector< vector<int> > data(count, vector<int>(5));
    for (int i = 0; i < count; i++) {
        for (int j = 0; j < 5; j++) {
            cin >> data[i][j];
        }
    }

    vector<int> resultIndices;

    for (int i = 0; i < count; i++) {
        bool isGood = true;
        for (int j = 0; j < count; j++) {
            if (j == i) continue;
            for (int k = j + 1; k < count; k++) {
                if (k == i) continue;
                Vector vec1(data[i].data(), data[j].data());
                Vector vec2(data[i].data(), data[k].data());
                double angleBetween = acos(vec1.prod(vec2) / (vec1.mag() * vec2.mag()));
                if (angleBetween < PI / 2 - epsilon) {
                    isGood = false;
                    goto outer_break;
                }
            }
        }
        outer_break:
        if (isGood) {
            resultIndices.push_back(i + 1);
        }
    }

    cout << resultIndices.size() << "\n";
    for (int index : resultIndices) {
        cout << index << "\n";
    }

    return 0;
}

